export function formatEthiopianTime(d: Date): string {
  const h = d.getHours(); const et = ((h + 6) % 12) || 12;
  const p = h >= 6 && h < 12 ? 'ጠዋት' : h === 12 ? 'ቀትር' : h > 12 && h < 18 ? 'ከሰዓት' : h >= 18 ? 'ማታ' : 'ለሊት';
  return `${et}:${String(d.getMinutes()).padStart(2,'0')} ${p}`;
}

export function ethiopianFiscalYearRange(efy: number) {
  return { start: toIsoDateLocal(ethiopianToGregorian({year: efy - 1, month: 11, day: 1})),
           end:   toIsoDateLocal(ethiopianToGregorian({year: efy,     month: 10, day: 30})) };
}

